def factorial(n):
	"""
	Return n! - the factorial of n.

	>>> factorial(1)
	1
	>>> factorial(0)
	1
	>>> factorial(3)
	6

	"""	
	if n<=0:
		return 0
	elif n==1:
		return 1
	else:
		return n*factorial(n-1)

