""" This gets the time in hours, mins and seconds """
def spltime(tseconds: Any) -> object {
    hours = tseconds // 3600;
    minutes = int((tseconds / 60)) % 60;
    seconds = tseconds % 60;
    return (hours, minutes, seconds);
}

